import{_ as t,a,b as o}from"./chunks/8e4497d86fe115285f8c.CvAobtPE.js";import{_ as l,C as i,o as s,c as n,j as e,a as h,E as c,a5 as u}from"./chunks/framework.DNkHA0lr.js";const x=JSON.parse('{"title":"你有责任在20多岁时变得富有","description":"","frontmatter":{"title":"你有责任在20多岁时变得富有","originalTitle":"You Are Obligated To Get Rich In Your 20s","date":"2024-02-23","originalUrl":"https://thedankoe.com/letters/you-are-obligated-to-get-rich-in-your-20s/","minutes":14,"sourceHash":"c723a46d0eb9b91151352effccfa1a41f332a4b736940224e00095c74c0cd28f","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/you-are-obligated-to-get-rich-in-your-20s/"}]]},"headers":[],"relativePath":"letters/you-are-obligated-to-get-rich-in-your-20s.md","filePath":"letters/you-are-obligated-to-get-rich-in-your-20s.md"}'),d={name:"letters/you-are-obligated-to-get-rich-in-your-20s.md"};function g(m,p,b,f,_,k){const r=i("ArticleMeta");return s(),n("div",null,[p[0]||(p[0]=e("h1",{id:"你有责任在20多岁时变得富有",tabindex:"-1"},[h("你有责任在20多岁时变得富有 "),e("a",{class:"header-anchor",href:"#你有责任在20多岁时变得富有","aria-label":'Permalink to "你有责任在20多岁时变得富有"'},"​")],-1)),c(r),p[1]||(p[1]=u('<p><a href="https://www.youtube.com/embed/AQpP-rhlz24?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p><img src="'+t+'" alt=""></p><p>我一直因为想赚钱而感到愧疚。</p><p>有一种潜意识的污名——赚钱是一件邪恶的事。这就是那些人生没什么成就的人整天挂在嘴边的说教。</p><p>我没意识到金钱可以成为精神成长的载体。</p><p><em>先说这一点：</em></p><p><em>不要因为想赚钱而感到愧疚。</em></p><p>金钱是让你满足基本需求的工具。它是生存的必需品。大多数人拒绝承认自己对金钱的需要（而不仅仅是想要），把自己困在一种狭隘的生存状态里。</p><p>金钱是解决问题的工具。</p><p>问题是对你心智和潜力的限制。当你解决了一个真实的问题，并把解决方案传承下去，你就为人类的进化做出了贡献。</p><p>创业是你能做的最具灵性的事情之一。</p><p>你在精神层面上有责任在20多岁时变得富有，因为在当今这个世界，金钱是个人发展的一道屏障。如果基本需求得不到满足、没有有意义的工作让你专注投入，更高层次的意识状态是很难达到的。</p><p>没有钱，你很可能会被困在那种默认的生活方式里：上学、做一份你讨厌的工作、和一个你根本不在乎的人结婚，然后有一天醒来，惊觉时间都去哪儿了。</p><h3 id="商业作为精神成长的载体" tabindex="-1">商业作为精神成长的载体 <a class="header-anchor" href="#商业作为精神成长的载体" aria-label="Permalink to &quot;商业作为精神成长的载体&quot;">​</a></h3><blockquote><p>你正被吸引向自己最高版本的样子，你内心的深处能感受到这一点。这种向外的进化召唤，要求你向内凿开那些经由你的成长条件层层堆叠起来的心理构造。——<a href="https://theartoffocusbook.com/" target="_blank" rel="noreferrer">《专注的艺术》</a></p></blockquote><p>最大的问题是：</p><p>大多数人拒绝追求物质对象，是因为他们看不透那个物质对象背后的东西。</p><p>有人可能一时冲动买了一辆豪车，但这并不意味着这件事必须停留在纯粹的物质追求层面。</p><p>他们可以逐渐痴迷于这辆车本身的深度。他们可以研究它的零件，把它变成一份事业,把它当作通往心流状态的入口。</p><p>教训：肤浅的追求也可以孕育出形而上的意义。</p><p>有人可能是出于对地位和金钱的追求而开始创业，但正是这份事业，能让他们接触到技能的深度、客户成果的深度，以及经营这份事业所需要的内心运作机制的深度。他们爱上了现实中那个缝隙，而那个现实的缝隙又教会了他们关于现实本身的道理。</p><p>对金钱的追求，几乎总是从肤浅开始的。</p><p>这并不意味着这是一件坏事。</p><p>这可能是让你接触到深度的唯一途径。</p><p>就像举铁一样。你一开始是为了外表好看，后来留下来是因为它成了一种疗愈。</p><p>当你找到以下三者的交集时：</p><ul><li>什么能让你生存下去</li><li>什么是你每天都乐在其中的事</li><li>什么能帮助别人变得更好</li></ul><p>人生就变得有意义、且充盈丰盛。</p><p>没错，赚钱这件事确实伴随着一些“不好”的部分。</p><p>就像一首歌也会有一些“不好”的歌词一样。</p><p>欢迎来到人生。你永远无法摆脱不好的那部分。你只能学着拉远视角，培育一个对未来的强大愿景，并确保这整个总体叙事最终导向天堂，而不是地狱。</p><p>大多数人永远达不到这个阶段，因为他们要等热情培养出来之后才愿意去追求一个目标。</p><p>你一开始并不是充满热情的。</p><p>你的热情，是根据你投入到这个目标上的能量多少而培养出来的。</p><p>所有的追求一开始都是物质性的，直到一种哲学意义上的精通感形成之后，它才会变成你通向未知、拓展和进化的载体。就像一段关系，一开始你是被外表吸引的（95%的情况都是如此），只有之后你才会接触到对方存在的深度。</p><p>在生活的各个领域，外表都和深度同样重要。问题在于，很多人从来没有真正深入下去。他们像一个心神不定的多巴胺瘾君子一样，只在表面来回蹦跳。</p><p>他们的心智不断重播那熟悉的过去和已知的未来。</p><p>他们一遍又一遍地重复同样的经历,却从未解决那些白白占据在他们脑子里、不付租金的问题——那些必须被解决,才能让他们进化到超越当前心智和处境的问题。</p><p>最终，你必须把那些“心理房客”赶出去,让新的房客住进来。</p><p>每一个外在的问题，都要求一个内在的问题被解决。</p><p>如果你不去追求一个看似肤浅的“本可以怎样”的目标来逆转熵增，你的心智、你客户的心智,乃至宇宙本身都会陷入混乱。</p><p>你之所以还没到达你想去的地方，是因为你还没有解决那个能解锁你下一个心智层次的问题。</p><h2 id="金钱是一种精神能量——去中心化的新经济" tabindex="-1">金钱是一种精神能量——去中心化的新经济 <a class="header-anchor" href="#金钱是一种精神能量——去中心化的新经济" aria-label="Permalink to &quot;金钱是一种精神能量——去中心化的新经济&quot;">​</a></h2><p><img src="'+a+'" alt=""></p><p>大多数人不理解什么是灵性。</p><p>他们被灵性吸引，是因为它承诺能缓解他们的痛苦，然后他们对此误解一通,附着上一个留长发、穿嬉皮士服装的新身份，好让自己感觉与众不同（甚至可能比别人更“高尚”）。</p><p>灵性是你与某个比自身更宏大的东西之间的连接。</p><p>灵性是与你所属的整体融为一体。</p><p>体育运动可以是一种灵性体验，因为你与整个团队融为一体。这就叫“团队精神”。</p><p>工作也可以是一种灵性体验，因为你与自己工作的影响力融为一体。“心流状态”常常被描述为一种灵性体验。</p><p>灵性,就是构成你自我的那些界限的消解。</p><p>商业给你一个成为有灵性的人的理由。</p><p>它让你接触到新的问题，这些问题需要一种全新的视角才能应对。</p><p>大多数人还停留在十年前的原地。他们不需要读更多关于灵性的东西，他们需要挑战自己，被迫把自己发展到一个不得不借助灵性才能到达下一阶段的程度。</p><p>转变到一种灵性视角，能让你理解金钱是一种能量，通过解决问题来推动成长、扩展和进化。</p><p>“转变到一种灵性视角”，就是拉远距离去观察现实。</p><p>当你这样做时，你会注意到自然的规律：</p><ul><li>统一与分裂</li><li>创造与毁灭</li><li>中心化与去中心化</li></ul><p>如其在上，如其在下。</p><p>现实是终极的心智模型。这种灵性视角正是富人和成功者背后的“秘密”。他们把自然的规律运用到自己每天的行动中。他们观察市场，理解其走向，并据此做出明智的决策。</p><p>很少有人察觉到的一个大规律，就是从公司向个人的转变。</p><ul><li>自由职业者占劳动力总数的46.6%（相比2020年的36%大幅上升）。</li><li>预计创作者经济将从2500亿美元翻倍增长到2028年的4800亿美元。人们以为自己来晚了，其实这场盛宴才刚刚开始。</li><li>经济更偏爱盈利能力高的商业模式。像创作者这样受科技赋能的业务，凭借数字产品和服务可以做到95%的利润率——这促使该领域涌现出更多新平台和新工具的开发。</li><li>大公司要求自己的领导层在社交媒体上保持活跃，以维护品牌声誉。企业化的营销正在减少，人性化的营销正在增多。</li></ul><p>各大公司开始更倾向于选用承包商和创作者作为员工与营销人员。</p><p>我们Kortex的团队是由承包商和创作者驱动的。我们没有雇员。我们通过创作者的受众来产生流量，并通过合同制工作,给团队成员灵活的工作日安排。</p><p>从灵性的视角来看，把你真实的自我转化为一份事业，其中的安全感其实不难看出。</p><h2 id="创作者哲学——它不只是一份网络上光鲜的工作-而是一种生活方式" tabindex="-1">创作者哲学——它不只是一份网络上光鲜的工作，而是一种生活方式 <a class="header-anchor" href="#创作者哲学——它不只是一份网络上光鲜的工作-而是一种生活方式" aria-label="Permalink to &quot;创作者哲学——它不只是一份网络上光鲜的工作，而是一种生活方式&quot;">​</a></h2><p><img src="'+o+'" alt=""></p><p>创作者哲学不是一种商业模式，而是一种生活方式。</p><p>提升自己，去帮助那些想要被帮助的人提升。</p><p>解决你自己的问题，把解决方案卖出去。</p><p>掌控自己，就是掌控世界。</p><p>以下是你今天就可以开始行动的步骤：</p><h3 id="_1-掌握你的生存-解决你自己的问题" tabindex="-1">1）掌握你的生存（解决你自己的问题） <a class="header-anchor" href="#_1-掌握你的生存-解决你自己的问题" aria-label="Permalink to &quot;1）掌握你的生存（解决你自己的问题）&quot;">​</a></h3><p>当你<em>需要</em>从别人那里得到某种东西时，你是无法维持真实性的。</p><p>金钱是一种工具，用来消除那些让你变得不真实的依赖关系。</p><p>地球上每一个个体都必须实现自我实现，才能以自己最好的方式为人类做出贡献。而人类的整体强度取决于其最薄弱的一环。一份事业能让你遭遇真正的问题，去解决它们，并把能够拓展他人心智的产品传承下去。</p><p>虽然这也可以通过完美的职业道路来实现，但那不是我能帮上忙的地方。而且那也不是你能完全掌控的事情。</p><p>创业就是现代版的生存。</p><p>我们狩猎资源（在现代意义上就是金钱）来满足自己的需求,并<em>创造</em>出我们喜欢的工作。而如果我们不喜欢某些方面，一份事业可以让你把工作中的那部分消除、委派或自动化掉。</p><p>我的建议依然和我所有的信件里说的一样：</p><ul><li>解决你生活中表面上的问题</li><li>让自己在多个维度上都变得强大（心智、身体、金钱和人际关系）</li><li>通过提升和构建，去发现你更深层的兴趣和痴迷所在</li><li>用内容和产品在互联网上记录你的旅程和解决方案</li></ul><p>95%的人的问题都围绕着健康、财富、人际关系和幸福感。</p><p>如果你能在自己的生活中解决这些问题，并把解决方案记录下来，你就能为你获得的知识收取费用。</p><p>我们在上一封信<a href="/letters/zero-to-1-million-as-a-one-person-business-while-working-2-4-hours-per-day">《从零到一百万美元：作为一人企业》</a>里讨论过这一点。</p><p>人们从领先自己十步的人那里学得并不最好，而是从领先自己一步的人那里学得最好。</p><h3 id="_2-创造你自己的哲学" tabindex="-1">2）创造你自己的哲学 <a class="header-anchor" href="#_2-创造你自己的哲学" aria-label="Permalink to &quot;2）创造你自己的哲学&quot;">​</a></h3><p>关于如何赚钱、如何约到炮，以及各种用来敷贴在心理健康上的“绊创膏”式建议，市面上已经够多了、够肤浅了。</p><p>我们需要更多的人成为真理的探寻者。</p><p>这些人明白，那些预先设定好的一步步式建议，表面上看起来光鲜，内里却是空洞的。</p><p>我们需要更多人去攻克问题的根源，而这根源往往是形而上学的、灵性的，或者是认识论层面的。</p><p>这个世界迫切地渴求深度，而深度只能通过开辟自己的道路来创造出来。</p><p>哲学是建立在经验之上的。</p><p>深度是通过实验和痴迷创造出来的。</p><p>你必须去尝试不同的技能和兴趣，直到找到那个能让商业对你而言变得具有灵性意义的东西。那个你无法停止不断深挖下去的东西。把你的旅程记录在互联网上（这个集体意识）,供所有人从中学习。</p><p>你必须把心智锚定在一个理想的未来上，全心全意地去追求它，犯下错误，<a href="https://kortex.co/" target="_blank" rel="noreferrer">记录你的经验教训</a>，并用一个可持续的解决方案来纠正你的行动。</p><p>你的哲学，是你为美好人生提出的一种世界观和生活方式。</p><p>人们需要在哪些技能、信念和习惯上得到教育？</p><p>对于我自己“少工作、多赚钱、享受生活”的哲学而言——人们需要营销、销售、写作、互补性的可变现技能、成长型思维、对形而上学的热情、每日的运动、每日的写作、每日的问题解决，以及每日的休息。这就是我所有内容的核心所在。</p><p>这就是我在 <a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">2 Hour Writer</a> 和 <a href="https://digitaleconomics.school/" target="_blank" rel="noreferrer">Digital Economics</a> 中教授的内容。</p><p>它并不适用于所有人。这正是重点所在。</p><p>你的工作是吸引像你一样的人，让别人去吸引像他们那样的人。</p><h3 id="_3-把它变成一所公立学校" tabindex="-1">3) 把它变成一所公立学校 <a class="header-anchor" href="#_3-把它变成一所公立学校" aria-label="Permalink to &quot;3) 把它变成一所公立学校&quot;">​</a></h3><blockquote><p>我深信，未来的学校教育将在网上进行，创作者就是老师，每个学生都可以加入最符合他们兴趣、价值观和偏好学习方式的“学校”。——<a href="https://theartoffocusbook.com/" target="_blank" rel="noreferrer">The Art Of Focus</a></p></blockquote><p><em>同一种学校体制不应该主导某人超过 12 年的生命。</em></p><p>学生们应该在几年后超越某个基于创作者的“学校”，进入下一个学校，并最终能够创办自己的学校——前提是这些其他学校拥有批判性思维和个人经验这一底层原则。</p><p>把创建知识库作为你毕生的事业，并在你的品牌（或学校）名义下将其在线分享，用一种底层哲学去吸引对的人。</p><p>你的公立学校就是数字房地产。</p><p>用 Twitter、Instagram 和 LinkedIn 来吸引广泛的受众。</p><p>用 YouTube、播客、博客或时事通讯来教育和培育受众。</p><p>以及一系列产品，从低价课程、会员服务到高价的定制教练辅导。</p><p>这就是我致力于教授的内容，因为我看到了这个领域的机遇。</p><p>最终，你会获得资源，去创办任何你想要的业务，以进一步传播你的信息。</p><p>我们在 <a href="https://university.kortex.co/" target="_blank" rel="noreferrer">Kortex University</a> 中指导你完成这一切，让你在 90 天内开启你的数字职业生涯。</p><h2 id="整体综合者——一份有意义的职业" tabindex="-1">整体综合者——一份有意义的职业 <a class="header-anchor" href="#整体综合者——一份有意义的职业" aria-label="Permalink to &quot;整体综合者——一份有意义的职业&quot;">​</a></h2><p>在这种哲学下，创作者经济不可能饱和，因为：</p><p><strong>1) 你的社区在进化</strong></p><p>当你不认同某个特定的标签、细分领域，或那些限制你能力的现实区隔时，你唯一的选择就是进化。</p><p>人类和社区不会固守一个目标。</p><p>一旦你实现了那个目标，你就会走向下一个显现出来的目标。</p><p><strong>2) 你的产品在进化</strong></p><p>我最初是一名网页设计师，我的产品和服务都围绕着这一点。</p><p>随着我发展自我和我的业务，我逐渐过渡到了不同的技能和兴趣上。</p><p>我的产品也随之改变，而我也有效地为我留下的网页设计市场去除了饱和度。</p><p><strong>3) 独特的兴趣网络</strong></p><p>当你深入探索那些构成你哲学的真实兴趣组合时，你的品牌就不再是割裂的了。</p><p>一个谈论健身、商业和科技的人，与一个谈论健身、商业和灵性的人仍然截然不同。</p><p><strong>4) 大型创作者拥有充足的资源</strong></p><p>看到大型创作者在各个方面减少产出并不罕见。</p><p>去看看拥有超过 100 万订阅者的 YouTuber 吧。</p><p>大约有 50% 的情况下，你会发现他们几乎不发视频，或者完全停止更新了。</p><p>X 的创作者也是如此。大号的更新频率通常会降到每周几次。</p><p>这让新创作者有机会涌入市场，吸引更多注意力，并建立人脉和资源，而无需面临来自“大玩家”的激烈竞争。</p><p>大玩家们继续追求新的目标，比如组建家庭，或者利用他们现在拥有的杠杆建立一家独立的公司。</p><p><strong>对深度的需求</strong></p><p>我们在创作者经济中已经达到了一个关键的临界点。</p><p>内容平台已经充斥着为了增长而制造的肤浅、基础和老调重弹的观点。</p><p>这未必是坏事，而且仍然能让账号涨粉，但我的问题是……为什么？</p><ul><li>为什么要过度系统化想法？</li><li>为什么要剥夺你业务的灵魂？</li><li>为什么要将增长、收入和肤浅的影响力凌驾于一切之上？</li><li>为什么要限制唯一能让你作为个体脱颖而出的东西：你的创造力？</li></ul><p>这个领域的普遍认知水平正在提升。</p><p>市场将要求创作者超越那些烂大街的名言警句和千篇一律的步骤化自助建议。</p><p>只有当你把深度、视角和整体综合放在首位时，才能做到这一点。</p><p><strong>整体综合者</strong></p><p>让我们来定义什么是“整体综合者”：</p><p><em>一个追求自身愿景，并利用自己获得的独特技能和兴趣开辟道路的人。他们不把这些技能或兴趣看作独立的个体，而是看作一个相互联系的整体，是他们生活中不可或缺的方面（而不是为了赚快钱的临时拼凑）。他们毕生的事业就是在这条道路上提炼、教育并传播他们的个人经验。</em></p><p>简而言之，整体综合者以一种具有说服力和教育意义的方式记录了他们对美好生活的追求。</p><p>这样一来，你就能吸引与你的声音产生共鸣的社区，帮助他们实现共同的目标，并且不会将自己局限于某个割裂的现实角落。</p><ul><li><strong>你的品牌就是你的哲学</strong>——一个人如何过上美好生活？</li><li><strong>你的内容就是你的学校</strong>——他们需要什么样的技能组合与思维方式？</li><li><strong>你的产品就是地图</strong>——一个整体的系统，帮助人们用更少的试错成本达到你现在的高度</li></ul><p>在更实用的层面上，以下是如何开始：</p><p><strong>1) 确定一个渴望的目标</strong></p><p>在你的生活中，你正试图实现或已经实现的一个大目标是什么？</p><p>你的身材好吗？你掌握了某种技能（比如写作）吗？你理解了现实的本质吗？它到底是什么？你完成了什么，无论你觉得它有多么微小或微不足道？</p><p>关键在于：</p><p>不要只关注目标本身，而要关注它为你创造的生活方式。</p><p><strong>2) 确定你的起点</strong></p><p>是什么让你想要改变？</p><p>你生活中最迫切的问题是什么？</p><p>在实现目标之前，你的生活是什么样的？</p><p>营销就是关于转变。</p><p>你是在帮助别人从 A 点（你曾经所在的地方）走到 B 点（令人渴望的目标）。</p><p><strong>3) 勾勒一条独特的道路</strong></p><p>现在，勾勒出从 A 点到 B 点所必需的模块、章节或步骤。</p><p>你处于人生的一个节点，可以回头帮助别人避开你曾犯过的错误。</p><p>就像你正在列一本书的提纲一样。</p><p>填补空白，写下人们为了实现目标所需要知道、学习和去做的<em>每一件事</em>。想想技能组合和思维方式。</p><p>互联网赋予了你自我教育的能力，其速度比人类史上任何人都要快得多。</p><p>承担起改善自己生活的责任，追寻你的好奇心，并分享你的发现。</p><p>还有什么比这更好的事吗？</p><p>在你去创办一家价值十亿美元的科技公司之前，考虑从唯一重要的事情开始：</p><p><em>改善每个人为了进化都必须改善的一件事：人类体验的质量。</em></p><p>当更多的人掌控了自己的个人生活，他们就能把大脑的创造力汇聚在一起，去解决全球性问题。</p><p>到你真正去做的时候，你就会知道该怎么做了。</p><p>你将成为一个大型创作者，去探索新的途径，并为你身后的市场“去饱和”。</p><p>感谢阅读这封信。</p><p>Dan</p><hr><p><a href="/en/letters/you-are-obligated-to-get-rich-in-your-20s">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',176))])}const T=l(d,[["render",g]]);export{x as __pageData,T as default};
